import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Computes the premium of a policy according to the MHPCO price list. */
public class PremiumCalculator {

    private static final int PROCESSING_FEE = 5;

    public int quote(List<Item> items, Customer customer, int previousContracts) {
        return basePremium(items) + PROCESSING_FEE;
    }

    /**
     * The policy base premium: the sum of all item base premiums, where components of one
     * type are priced as a block if there are exactly {@link PriceList#BLOCK_SIZE} of them.
     */
    private int basePremium(List<Item> items) {
        Map<String, Integer> componentCounts = new LinkedHashMap<>();
        int base = 0;
        for (Item item : items) {
            if (PriceList.isComponent(item.type())) {
                componentCounts.merge(item.type(), 1, Integer::sum);
            } else {
                base += PriceList.basePremium(item.type());
            }
        }
        for (Map.Entry<String, Integer> counted : componentCounts.entrySet()) {
            base += componentsPremium(counted.getKey(), counted.getValue());
        }
        return base;
    }

    private int componentsPremium(String type, int count) {
        if (count == PriceList.BLOCK_SIZE) {
            return PriceList.BLOCK_BASE_PREMIUM;
        }
        return count * PriceList.basePremium(type);
    }
}
