import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Computes the premium of a policy according to the MHPCO price list. */
public class PremiumCalculator {

    private static final BigDecimal PROCESSING_FEE = BigDecimal.valueOf(5);
    private static final BigDecimal CURSE_SURCHARGE = new BigDecimal("0.5");
    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE = new BigDecimal("0.3");
    private static final int HIGH_ENCHANTMENT_LEVEL = 5;

    public int quote(List<Item> items, Customer customer, int previousContracts) {
        BigDecimal premium = policyBasePremium(items);
        return premium.add(PROCESSING_FEE).setScale(0, RoundingMode.CEILING).intValueExact();
    }

    /** The sum of all item base premiums including the item-specific risk surcharges. */
    private BigDecimal policyBasePremium(List<Item> items) {
        BigDecimal base = BigDecimal.ZERO;
        Map<String, List<Item>> componentsByType = new LinkedHashMap<>();
        for (Item item : items) {
            if (PriceList.isComponent(item.type())) {
                componentsByType.computeIfAbsent(item.type(), type -> new java.util.ArrayList<>()).add(item);
            } else {
                base = base.add(withItemModifiers(item, BigDecimal.valueOf(PriceList.basePremium(item.type()))));
            }
        }
        for (List<Item> alike : componentsByType.values()) {
            base = base.add(componentsPremium(alike));
        }
        return base;
    }

    /**
     * Components of one type are priced as a block if there are exactly
     * {@link PriceList#BLOCK_SIZE} of them; the block price is shared equally among them so
     * that item-specific surcharges still apply per item.
     */
    private BigDecimal componentsPremium(List<Item> alike) {
        BigDecimal each = alike.size() == PriceList.BLOCK_SIZE
                ? BigDecimal.valueOf(PriceList.BLOCK_BASE_PREMIUM)
                        .divide(BigDecimal.valueOf(PriceList.BLOCK_SIZE))
                : BigDecimal.valueOf(PriceList.basePremium(alike.get(0).type()));
        BigDecimal total = BigDecimal.ZERO;
        for (Item component : alike) {
            total = total.add(withItemModifiers(component, each));
        }
        return total;
    }

    private BigDecimal withItemModifiers(Item item, BigDecimal base) {
        BigDecimal surcharge = BigDecimal.ZERO;
        if (item.cursed()) {
            surcharge = surcharge.add(CURSE_SURCHARGE);
        }
        if (item.enchantment() >= HIGH_ENCHANTMENT_LEVEL) {
            surcharge = surcharge.add(HIGH_ENCHANTMENT_SURCHARGE);
        }
        return base.add(base.multiply(surcharge));
    }
}
EOF
mvn -q -o test 2>&1 | grep -E "Tests run:|expected:" | head -8; echo "---"

